// The sand bike's visuals (public/models/sandbike.glb, generated by tools/blender/sandbike.py). Physics is
// shared/sim.ts stepBike(); this only draws it: pitched along the sand (or the flight path in the air),
// leaning into turns, wheels spinning with the ground speed, the bars turned with the steering, a tyre
// track behind it, the front wheel up while Space is held (a wheelie; letting go hops). The rider (an Avatar) sits in the bike's tilted frame; rider() says where its hips, hands
// and feet go (the hands follow the bars), and how it leans into turns, twists with the bars, and tucks
// forward (rocking back as it accelerates). After dark its headlight comes on: a shadow-casting spotlight from
// the lamp that turns with the bars, and the lens glows.
import * as THREE from 'three/webgpu';
import { GLTFLoader, type GLTF } from 'three/addons/loaders/GLTFLoader.js';
import { slopeAt } from '../shared/sim.ts';
import { heightAt } from '../shared/terrain.ts';
import { END_FADE, TRACK_WRAP, tyreprints } from './footprints.ts';
import { tyreDust } from './tyreDust.ts';
import { bikeLandSound } from './bikeLandSound.ts';
import type { RidePose } from './players.ts';
import { nightLevel, SHADOW_ONLY_LAYER } from './world/env.ts';
import { applyTier } from './tierLook.ts';

// Rider contact points, in the bike's frame (origin on the ground between the tyres, forward is -z), from
// tools/blender/sandbike.py: hips over the front of the seat (top 0.86), ankles over the pegs (0.2, 0.34, 0.12).
const SEAT = new THREE.Vector3(0, 0.97, 0.24);
const PEG = new THREE.Vector3(0.2, 0.42, 0.14);
/** The right grip's middle, in the Handlebar node's frame (its origin is the steering head). */
const GRIP = new THREE.Vector3(0.334, 0.184, 0.151);
const WHEEL_R = 0.37;
const WHEELBASE = 1.36;
/** The fork is raked 24°: the bars turn about this axis, not straight up. */
const STEER_AXIS = new THREE.Vector3(0, 0.9135, 0.4067);
const MAX_LEAN = 0.6;
const MAX_STEER = 0.5;
const TRACK_STEP = 0.3; // metres per tyre-track strip (short, so turns curve smoothly)
const WHEELIE = 0.45; // rad the nose comes up, about the rear tyre's contact
const BIG_AIR = 0.6; // s in the air before a landing throws up a cloud and thumps
/** The headlight lens in the Handlebar node's frame (tools/blender/sandbike.py lamp_c), and where the beam
 *  aims from there: ahead and a little down, so it pools on the sand ~15 m out. */
const LAMP = new THREE.Vector3(0, 0.076, -0.25);
const AIM = new THREE.Vector3(0, -0.06, -1);
const HEADLIGHT = { color: 0xffe4bc, intensity: 30, distance: 45, angle: 0.5, penumbra: 0.8, decay: 1.2, glow: 6 };
/** Its shadow map: the near plane clears the lamp housing around the lens, so the bike only shadows what's ahead. */
const HEADLIGHT_SHADOW = { map: 1024, near: 0.3, bias: -0.0005, normalBias: 0.03 };
/** Headlights are a fixed pool that stays in the scene (adding or removing a light recompiles every material);
 *  a bike that finds none free rides without one. */
const POOL = 3;
const headlights: { light: THREE.SpotLight; used: boolean }[] = [];

/** Put the headlight pool in the scene at startup, behind the loading cover: done on the first ride instead,
 *  the recompile froze the game for a moment. Also starts loading the model. */
export function addHeadlights(scene: THREE.Scene) {
  load();
  if (headlights.length) return;
  for (let i = 0; i < POOL; i++) {
    const h = HEADLIGHT;
    const light = new THREE.SpotLight(h.color, 0, h.distance, h.angle, h.penumbra, h.decay);
    const s = HEADLIGHT_SHADOW;
    light.castShadow = true; // always on (toggling recompiles too), but the map only renders while lit
    light.shadow.autoUpdate = false;
    // Render the map once up front: if materials sample it before its first render, that render
    // recreates the depth texture under their cached bind groups ("Destroyed texture used in a submit").
    light.shadow.needsUpdate = true;
    light.shadow.mapSize.set(s.map, s.map);
    light.shadow.camera.near = s.near;
    light.shadow.camera.layers.enable(SHADOW_ONLY_LAYER); // the local rider's own body
    light.shadow.bias = s.bias;
    light.shadow.normalBias = s.normalBias;
    scene.add(light, light.target);
    headlights.push({ light, used: false });
  }
}

let shared: Promise<GLTF> | undefined;
const load = () => (shared ??= new GLTFLoader().loadAsync('./models/sandbike.glb'));
/** The sand bike model (shared by every clone: don't change its materials), also drawn lying broken on the sand (src/world/loot.ts). */
export const loadBikeModel = load;

export type BikePose = { x: number; y: number; z: number; heading: number; vx: number; vy: number; vz: number; grounded: boolean;
  /** Space held: up on the back wheel while grounded. */
  jumpHeld: boolean };

export class Bike {
  readonly root = new THREE.Group(); // on the ground under the bike, turned to its heading
  private tilt = new THREE.Group(); // pitch along the ground, lean into turns
  private front?: THREE.Object3D;
  private rear?: THREE.Object3D;
  private bars?: THREE.Object3D;
  private heading = NaN;
  private pitch = 0;
  private wheelie = 0;
  private lean = 0;
  private steer = 0;
  // Where the tyre track last ended, and the path distance there (keys the tread pattern).
  private trackX = NaN;
  private trackZ = NaN;
  private trackS = 0;
  private forward = NaN;
  private accel = 0;
  private grounded = true;
  private airTime = 0; // s since it left the ground
  private airV = new THREE.Vector3(); // velocity on the last frame in the air
  private dustOwed = 0; // puffs owed to tyreDust (fractional)
  private disposed = false;
  private headlight?: (typeof headlights)[number];
  private lens: THREE.MeshStandardMaterial[] = [];
  private model?: THREE.Object3D;
  /** How good the bike's parts are (src/tierLook.ts). */
  private tier = 1;
  private glow = 0; // 0..1, the headlight ramping on and off
  private readonly pose: RidePose = {
    seat: new THREE.Vector3(),
    grips: [new THREE.Vector3(), new THREE.Vector3()],
    pegs: [new THREE.Vector3(-PEG.x, PEG.y, PEG.z), PEG.clone()],
    lean: 0, twist: 0, tuck: 0,
  };

  constructor(scene: THREE.Scene) {
    this.tilt.rotation.order = 'YXZ';
    this.root.add(this.tilt);
    scene.add(this.root);
    addHeadlights(scene);
    this.headlight = headlights.find((h) => !h.used);
    if (this.headlight) this.headlight.used = true;
    load().then(
      (gltf) => {
        if (this.disposed) return;
        const model = gltf.scene.clone(true);
        model.traverse((o) => {
          const m = o as THREE.Mesh;
          if (!m.isMesh) return;
          m.castShadow = m.receiveShadow = true;
          // The lens gets its own material (clones share the model's), so each bike's glow is its own.
          const mat = m.material as THREE.MeshStandardMaterial;
          if (mat.name === 'lamp') {
            const lens = mat.clone();
            lens.emissive.setHex(HEADLIGHT.color);
            lens.emissiveIntensity = 0;
            m.material = lens;
            m.userData.noTier = true;
            this.lens.push(lens);
          }
        });
        this.front = model.getObjectByName('FrontWheel');
        this.rear = model.getObjectByName('RearWheel');
        this.bars = model.getObjectByName('Handlebar');
        this.tilt.add(model);
        this.model = model;
        applyTier(model, this.tier);
      },
      (e) => console.warn('sand bike model failed to load', e),
    );
  }

  /** The look of its parts' tier (0 Scrap .. 3 Space-grade). */
  setTier(tier: number) {
    this.tier = tier;
    if (this.model) applyTier(this.model, tier);
  }

  update(p: BikePose, dt: number) {
    const k = (rate: number) => 1 - Math.exp(-dt * rate);
    const hs = Math.hypot(p.vx, p.vz);
    if (!Number.isFinite(this.heading)) this.heading = p.heading;
    const turn = Math.atan2(Math.sin(p.heading - this.heading), Math.cos(p.heading - this.heading));
    this.heading = p.heading;
    const fx = -Math.sin(p.heading), fz = -Math.cos(p.heading);
    const forward = p.vx * fx + p.vz * fz;

    // Nose: along the sand on the ground, along the flight path in the air.
    let pitch: number;
    if (p.grounded) {
      const g = slopeAt(p.x, p.z, tmpSlope);
      pitch = p.y > heightAt(p.x, p.z) + 0.02 ? 0 : Math.atan(g.gx * fx + g.gz * fz);
    } else {
      pitch = Math.max(-0.7, Math.min(0.7, Math.atan2(p.vy, Math.max(hs, 4))));
    }
    this.pitch += (pitch - this.pitch) * k(p.grounded ? 14 : 4);
    const wheelie = p.grounded && p.jumpHeld ? WHEELIE : 0;
    this.wheelie += (wheelie - this.wheelie) * k(wheelie > this.wheelie ? 7 : p.grounded ? 12 : 3);
    // Lean so that gravity balances the turn: tan(lean) = v·ω / g.
    const rate = dt > 0 ? turn / dt : 0;
    const lean = p.grounded ? Math.max(-MAX_LEAN, Math.min(MAX_LEAN, Math.atan((forward * rate) / 25))) : this.lean * 0.98;
    this.lean += (lean - this.lean) * k(6);
    // Fore-aft acceleration (smoothed), for the rider rocking back on the throttle.
    if (dt > 0 && Number.isFinite(this.forward)) this.accel += ((forward - this.forward) / dt - this.accel) * k(5);
    this.forward = forward;
    const landed = p.grounded && !this.grounded;
    if (landed && this.airTime > BIG_AIR) this.bigLanding(p, hs);
    if (p.grounded) this.airTime = 0;
    else {
      this.airTime += dt;
      this.airV.set(p.vx, p.vy, p.vz);
    }
    this.grounded = p.grounded;
    const steer = Math.abs(forward) > 0.5 ? Math.max(-MAX_STEER, Math.min(MAX_STEER, Math.atan((rate * WHEELBASE) / forward))) : this.steer;
    this.steer += (steer - this.steer) * k(10);

    this.root.position.set(p.x, p.y, p.z);
    this.root.rotation.y = p.heading;
    // Pitch up about the rear contact: shift the frame so that point stays where the plain pitch puts it.
    const a = this.pitch, b = this.pitch + this.wheelie, rear = WHEELBASE / 2;
    this.tilt.position.set(0, rear * (Math.sin(b) - Math.sin(a)), rear * (Math.cos(a) - Math.cos(b)));
    this.tilt.rotation.x = b;
    this.tilt.rotation.z = this.lean;
    this.bars?.quaternion.setFromAxisAngle(STEER_AXIS, this.steer);
    const spin = (forward * dt) / WHEEL_R;
    if (this.front) this.front.rotation.x -= spin;
    if (this.rear) this.rear.rotation.x -= spin;
    this.lights(dt);

    // Tyre track and dust on the sand.
    if (!p.grounded || p.y > heightAt(p.x, p.z) + 0.05) {
      this.trackX = NaN; // airborne: the track breaks, and starts afresh where it lands
      return;
    }
    this.dust(p, fx, fz, hs, dt, landed);
    this.trackTo(p.x - fx * WHEELBASE * 0.5, p.z - fz * WHEELBASE * 0.5);
  }

  /** Extend the tyre track to the rear wheel at (x, z): a strip from where it last ended, once it is long enough. */
  private trackTo(x: number, z: number) {
    if (Number.isNaN(this.trackX)) {
      this.trackX = x;
      this.trackZ = z;
      return;
    }
    const dx = x - this.trackX, dz = z - this.trackZ;
    const len = Math.hypot(dx, dz);
    if (len < TRACK_STEP) return;
    if (len < 3) {
      const mx = this.trackX + dx / 2, mz = this.trackZ + dz / 2;
      // Stretched so each end fade overlaps the neighbouring strip's, and the joins blend.
      const strip = len / (1 - END_FADE);
      tyreprints.add(mx, heightAt(mx, mz), mz, Math.atan2(-dx, -dz), 1, strip, this.trackS + len / 2, strip);
      this.trackS = (this.trackS + len) % TRACK_WRAP;
    } // else a teleport or snapshot jump: start afresh
    this.trackX = x;
    this.trackZ = z;
  }

  /** The headlight: on once it is dark (the sun a couple of degrees under), with a quick ramp so it doesn't pop. */
  private lights(dt: number) {
    const on = nightLevel.value > 0.05 ? 1 : 0;
    this.glow += (on - this.glow) * (1 - Math.exp(-dt * 12));
    if (this.glow < 1e-3) this.glow = 0;
    for (const m of this.lens) m.emissiveIntensity = HEADLIGHT.glow * this.glow;
    const h = this.headlight?.light;
    if (!h) return;
    h.intensity = this.bars ? HEADLIGHT.intensity * this.glow : 0;
    h.shadow.autoUpdate = h.intensity > 0;
    if (!h.intensity) return;
    this.root.updateMatrixWorld(true);
    this.bars!.localToWorld(h.position.copy(LAMP));
    this.bars!.localToWorld(h.target.position.copy(LAMP).add(AIM));
    h.updateMatrixWorld();
    h.target.updateMatrixWorld();
  }

  /** Sand off the back tyre: with speed, more when the back slides sideways, a burst on landing. */
  private dust(p: BikePose, fx: number, fz: number, hs: number, dt: number, landed: boolean) {
    const slip = Math.abs(-p.vx * fz + p.vz * fx);
    this.dustOwed += dt * (Math.max(0, hs - 1.5) * 1.4 + slip * 6) + (landed ? 12 : 0);
    const throwBack = Math.min(hs, 20) * 0.12;
    for (; this.dustOwed >= 1; this.dustOwed--) {
      const side = (Math.random() - 0.5) * 0.4;
      const x = p.x - fx * WHEELBASE * 0.5 - fz * side, z = p.z - fz * WHEELBASE * 0.5 + fx * side;
      const back = throwBack * (0.4 + Math.random()), spread = (Math.random() - 0.5) * 2;
      tyreDust.emit(x, heightAt(x, z) + 0.15, z, -fx * back - fz * spread, 0.8 + Math.random() * 1.6, -fz * back + fx * spread, 0.8 + Math.random() * 0.6 + hs * 0.045);
    }
  }

  /** Down after a long jump: a cloud of sand bursting out round the bike, bigger the longer the flight and the
   *  rougher the landing (and never quite the same twice), and a thump (rougher: a crash). */
  private bigLanding(p: BikePose, hs: number) {
    // How hard it hit: the speed into the sand across the slope, as the sim reckons it (shared/sim.ts stepBike).
    const g = p.y > heightAt(p.x, p.z) + 0.02 ? FLAT : slopeAt(p.x, p.z, tmpSlope);
    const impact = Math.max(0, g.gx * this.airV.x + g.gz * this.airV.z - this.airV.y);
    const strength = Math.min(1, Math.max(0, (this.airTime - BIG_AIR) / 1.6) * 0.4 + Math.max(0, (impact - 3) / 15) * 0.6);
    const size = (0.6 + strength) * (0.7 + Math.random() * 0.6);
    const n = Math.round(14 + 36 * size);
    const fx = p.vx / Math.max(hs, 1), fz = p.vz / Math.max(hs, 1);
    for (let i = 0; i < n; i++) {
      // Out in a ring, carried on a little with the bike, low and wide, the biggest puffs slowest.
      const a = Math.random() * Math.PI * 2, r = Math.random() * 0.8 * size;
      const x = p.x + Math.cos(a) * r, z = p.z + Math.sin(a) * r;
      const puff = (0.9 + Math.random() * 1.4) * size;
      const out = (2 + Math.random() * 5) * size / Math.sqrt(puff);
      tyreDust.emit(x, heightAt(x, z) + 0.2, z, Math.cos(a) * out + fx * hs * 0.25, 0.3 + Math.random() * 1.8 * size,
        Math.sin(a) * out + fz * hs * 0.25, puff, 3 + Math.random() * 3 * size);
    }
    bikeLandSound.play(p.x, p.z, impact);
  }

  /** How far the bike leans into the turn (rad, + = left). */
  get leanAngle() {
    return this.lean;
  }

  /** Put the rider's root in the bike's tilted frame (then pose it with rider()). */
  seat(rider: THREE.Object3D) {
    this.root.updateMatrixWorld(true);
    this.tilt.matrixWorld.decompose(rider.position, rider.quaternion, tmpScale);
  }

  /** Where the seated rider's hips, hands and feet go (in the bike's tilted frame, after seat()), and its body English. */
  rider(): RidePose {
    const r = this.pose;
    const turn = this.lean / MAX_LEAN; // -1..1, + = left
    // Hang off a little to the inside of the turn, lean further than the bike, turn the shoulders with the bars.
    r.seat.copy(SEAT).setX(-0.07 * turn);
    r.lean = 0.25 * turn;
    r.twist = 0.6 * this.steer;
    // Tucked forward; the throttle pushes the body back, braking throws it forward; crouched lower in the air,
    // leaning forward over the bars on a wheelie (it keeps the body upright while the bike rears).
    r.tuck = (this.grounded ? 0.42 : 0.55) + this.wheelie * 0.6 - Math.max(-0.2, Math.min(0.2, this.accel * 0.025));
    for (let i = 0; i < 2; i++) {
      const g = r.grips[i].set(i === 0 ? -GRIP.x : GRIP.x, GRIP.y, GRIP.z);
      if (this.bars) this.tilt.worldToLocal(this.bars.localToWorld(g));
      else g.add(BARS_PIVOT);
    }
    return r;
  }

  dispose() {
    this.disposed = true;
    this.root.removeFromParent();
    this.root.traverse((o) => o.dispose()); // bindings are per bike; geometry and tier materials are shared
    for (const material of this.lens) material.dispose();
    if (this.headlight) {
      this.headlight.light.intensity = 0;
      this.headlight.light.shadow.autoUpdate = false;
      this.headlight.used = false;
    }
  }
}

const tmpSlope = { gx: 0, gz: 0 };
const FLAT = { gx: 0, gz: 0 };
const tmpScale = new THREE.Vector3();
/** The Handlebar node's origin in the bike's frame, for the grips before the model has loaded. */
const BARS_PIVOT = new THREE.Vector3(0, 0.98, -0.408);
